Item.method_code:
interface Form {
	id: string;
};

interface FormInPackage extends Form {
	name: string;
	keyedName: string;
	packageName: string;
};

const instructUserToUseUpdatePackageAction = async (
	item: FormInPackage
	) => {
	if (!item) {
		return;
	}

	const errorMessage: string =
		getResource(
			'item_methods.package_with_form_already_exists',
			item.keyedName,
			options.itemTypeName,
			item.packageName
		);

	if (!errorMessage) {
		return;
	}

	const newLine = '\r\n';
	await alert(
		`${errorMessage}${newLine}${getResource(
			'item_methods.use_update_package_action_message'
		)}`
	);
}

const response : { formsToAdd: Form[]; formsToUpdate: FormInPackage[] } = await odataFetch('method.FilterFormItemsBeforePackage', {
	method: 'POST',
	body: JSON.stringify({
		ids: options.itemId
	})
});

if (response.formsToAdd && response.formsToAdd.length > 0) {
	await window.aras.addItemToPackageDef(response.formsToAdd, options.itemTypeName);
}

if (response.formsToUpdate && response.formsToUpdate.length == 1) {
	await instructUserToUseUpdatePackageAction(response.formsToUpdate[0]);
}
